import numpy as np
from scipy.optimize import least_squares
V=np.var(dA_dt)
forms={
 'satA_pos_exp': lambda p: -p[0]*t**p[1]*A**p[2]/(1+p[3]*A) + p[4]*A**p[5]*t**p[6]*np.exp(-p[7]*t),
 'expsat_pos_exp': lambda p: -p[0]*t**p[1]*(1-np.exp(-p[2]*A)) + p[3]*A**p[4]*np.exp(-p[5]*t)+p[6]*A*t**p[7],
 'MM_pos_powdecay': lambda p: -p[0]*t**p[1]*A/(p[2]+A) + p[3]*A**p[4]*t**p[5]*np.exp(-p[6]*t*A),
 'MM_pos2': lambda p: -p[0]*t**p[1]*A/(p[2]+A) + p[3]*A**p[4]/(1+p[5]*t**p[6]),
}
rng=np.random.default_rng(1)
for name,f in forms.items():
    best=(9,None)
    for k in range(40):
        p0=rng.uniform(-1.5,2,8)
